import math
class Solution:
    def closestDivisors(self, num: int) -> List[int]:
        def best(n):
            i = int(math.isqrt(n))
            while n % i:
                i -= 1
            return [i, n // i]
        a, b = best(num + 1), best(num + 2)
        return a if a[1] - a[0] <= b[1] - b[0] else b

